# Trains folds [0, 1] of my knee reader on 2x T4. Generated by src/make_train_kernel.py.
SOURCES = {'knee.py': '# Adapted from goodpjw2008\'s RSNA Knee 2.5D ConvNeXt reader (Apache 2.0):\n# https://www.kaggle.com/code/goodpjw2008/rsna-knee-stack-2-5d-convnext-mil-lb-0-944\n"""Shared dataset and model code for training and inference."""\nimport math\n\nimport numpy as np\nimport timm\nimport torch\nimport torch.nn as nn\nimport torch.nn.functional as F\n\nLABELS = ["ACL", "MCL", "Medial Meniscus", "Lateral Meniscus", "Medial OA", "Lateral OA",\n          "PF OA", "Effusion", "Synovitis", "Baker\'s", "Contusion", "Fracture"]\nPLANES = ["Sagittal", "Coronal", "Axial"]\n# slot = plane index + 3 * (1 - fat_suppressed): fat-suppressed planes first\nN_SLOTS = 6\nMEAN = (0.485, 0.456, 0.406)\nSTD = (0.229, 0.224, 0.225)\nCACHE_SIZE = 256  # must match preprocess.SIZE\n\n\ndef slot_of(plane, fat_sup):\n    return PLANES.index(plane) + 3 * (1 - int(fat_sup))\n\n\ndef build_study_table(series_df, n_slices):\n    """series_df: StudyInstanceUID, SeriesInstanceUID, Fat_Suppression, Anatomical_Plane.\n    n_slices: dict series -> cached slice count. Returns {study: [[series ids of slot 0], ...]}\n    with each slot\'s candidates sorted by slice count (largest first)."""\n    table = {}\n    for st, sr, fs, pl in zip(series_df.StudyInstanceUID, series_df.SeriesInstanceUID,\n                              series_df.Fat_Suppression, series_df.Anatomical_Plane):\n        if n_slices.get(sr, 0) < 3:\n            continue\n        table.setdefault(st, [[] for _ in range(N_SLOTS)])[slot_of(pl, fs)].append(sr)\n    for slots in table.values():\n        for cands in slots:\n            cands.sort(key=lambda s: -n_slices[s])\n    return table\n\n\ndef window_centres(n, k, train, lo=0.04, hi=0.96):\n    """k slice indices (centres of 3-slice windows) spread over the series."""\n    a, b = max(1.0, lo * (n - 1)), min(n - 2.0, hi * (n - 1))\n    if b < a:\n        a = b = (n - 1) / 2\n    if train:\n        edges = np.linspace(a, b, k + 1)\n        c = edges[:-1] + np.random.rand(k) * (edges[1:] - edges[:-1])\n    else:\n        c = np.linspace(a, b, k)\n    return np.clip(np.round(c).astype(int), 1, max(1, n - 2))\n\n\nclass StudyDataset(torch.utils.data.Dataset):\n    """One item = one study: uint8 windows [N_SLOTS, k, 3, H, W], slot mask, slice positions, target."""\n\n    def __init__(self, studies, table, cache_dir, targets=None, k=8, train=False, loader=None):\n        self.studies, self.table, self.cache_dir = list(studies), table, cache_dir\n        self.targets, self.k, self.train = targets, k, train\n        self.loader = loader or (lambda s: np.load(f"{self.cache_dir}/{s}.npy", mmap_mode="r"))\n\n    def __len__(self):\n        return len(self.studies)\n\n    def __getitem__(self, i):\n        st = self.studies[i]\n        slots = self.table.get(st, [[] for _ in range(N_SLOTS)])\n        x, mask, pos = None, np.zeros(N_SLOTS, bool), np.zeros((N_SLOTS, self.k), np.float32)\n        for s, cands in enumerate(slots):\n            if not cands:\n                continue\n            sr = cands[np.random.randint(len(cands))] if self.train else cands[0]\n            vol = self.loader(sr)\n            n = len(vol)\n            c = window_centres(n, self.k, self.train)\n            win = np.stack([vol[np.clip([j - 1, j, j + 1], 0, n - 1)] for j in c])  # [k, 3, H, W]\n            if x is None:\n                x = np.zeros((N_SLOTS, self.k) + win.shape[1:], np.uint8)\n            x[s], mask[s], pos[s] = win, True, c / max(n - 1, 1)\n        if x is None:\n            x = np.zeros((N_SLOTS, self.k, 3, CACHE_SIZE, CACHE_SIZE), np.uint8)\n        y = self.targets[i] if self.targets is not None else np.zeros(len(LABELS), np.float32)\n        return torch.from_numpy(x), torch.from_numpy(mask), torch.from_numpy(pos), torch.from_numpy(np.asarray(y, np.float32))\n\n\ndef make_views(x, res, train, group, fov=0.92, flip_ok=None):\n    """x: uint8 [N, 3, H, W] with N = n_series * group. Crops a centred `fov` fraction of the cached\n    field of view and resizes to res; in training adds rotation/scale/shift and gain/gamma jitter\n    that is shared within a series. flip_ok: bool [n_series]; where True the series may be mirrored\n    left-right (a coronal or axial knee mirrored is just the other knee)."""\n    n = x.shape[0]\n    ns = n // group\n    dev = x.device\n    x = x.float().div_(255.0)\n    if train:\n        ang = (torch.rand(ns, device=dev) - 0.5) * 2 * math.radians(12)\n        sc = fov * (1 + (torch.rand(ns, device=dev) - 0.5) * 0.24)\n        if flip_ok is not None:\n            flip = (torch.rand(ns, device=dev) < 0.5) & flip_ok.to(dev)\n            sc = torch.where(flip, -sc, sc)  # negative x-scale mirrors the image\n        tx = (torch.rand(ns, device=dev) - 0.5) * 0.12\n        ty = (torch.rand(ns, device=dev) - 0.5) * 0.12\n        gamma = torch.exp((torch.rand(ns, device=dev) - 0.5) * 0.5)\n        gain = 1 + (torch.rand(ns, device=dev) - 0.5) * 0.2\n    else:\n        ang = torch.zeros(ns, device=dev)\n        sc = torch.full((ns,), fov, device=dev)\n        tx = ty = torch.zeros(ns, device=dev)\n        gamma = gain = None\n    sy = sc.abs()  # only the x-axis carries the mirror sign\n    theta = torch.stack([torch.stack([torch.cos(ang) * sc, -torch.sin(ang) * sy, tx], 1),\n                         torch.stack([torch.sin(ang) * sc, torch.cos(ang) * sy, ty], 1)], 1)\n    theta = theta.repeat_interleave(group, 0)\n    grid = F.affine_grid(theta, (n, 3, res, res), align_corners=False)\n    if x.shape[-1] > 1.5 * res:  # avoid aliasing when shrinking a lot\n        x = F.avg_pool2d(x, 2) if x.shape[-1] >= 2 * res else F.interpolate(x, scale_factor=0.75, mode="bilinear", antialias=True)\n    x = F.grid_sample(x, grid, mode="bilinear", padding_mode="zeros", align_corners=False)\n    if train:\n        g = gamma.repeat_interleave(group).view(n, 1, 1, 1)\n        x = x.clamp_min(1e-4).pow(g) * gain.repeat_interleave(group).view(n, 1, 1, 1)\n    mean = torch.tensor(MEAN, device=dev).view(1, 3, 1, 1)\n    std = torch.tensor(STD, device=dev).view(1, 3, 1, 1)\n    return (x - mean) / std\n\n\nclass KneeNet(nn.Module):\n    """2D backbone on 3-slice windows -> tokens tagged with series slot and slice position ->\n    small transformer over all windows of the study -> one attention pooling per finding."""\n\n    def __init__(self, backbone="convnext_tiny", pretrained=True, dim=384, depth=2, drop=0.2, drop_path=0.1,\n                 img_size=None):\n        super().__init__()\n        kw = {"drop_path_rate": drop_path} if drop_path else {}\n        if img_size and backbone.startswith(("vit_", "eva", "beit")):  # fixed-grid transformers need the input size\n            kw["img_size"] = img_size\n        self.enc = timm.create_model(backbone, pretrained=pretrained, num_classes=0, **kw)\n        self.proj = nn.Sequential(nn.Dropout(drop), nn.Linear(self.enc.num_features, dim), nn.LayerNorm(dim))\n        self.slot_emb = nn.Embedding(N_SLOTS, dim)\n        self.pos_emb = nn.Sequential(nn.Linear(1, dim), nn.GELU(), nn.Linear(dim, dim))\n        layer = nn.TransformerEncoderLayer(dim, 8, dim * 2, dropout=0.1, batch_first=True, norm_first=True)\n        self.tf = nn.TransformerEncoder(layer, depth, enable_nested_tensor=False) if depth else None\n        self.att = nn.Sequential(nn.Linear(dim, 256), nn.Tanh(), nn.Dropout(drop), nn.Linear(256, len(LABELS)))\n        self.cls_w = nn.Parameter(torch.randn(len(LABELS), dim) * 0.02)\n        self.cls_b = nn.Parameter(torch.zeros(len(LABELS)))\n\n    def head(self, feat, mask, pos):\n        """feat [B, S, K, D], mask [B, S] bool, pos [B, S, K] in 0..1 -> logits [B, 12]."""\n        b, s, k, _ = feat.shape\n        slot = torch.arange(s, device=feat.device).view(1, s, 1).expand(b, s, k)\n        h = self.proj(feat) + self.slot_emb(slot) + self.pos_emb(pos.unsqueeze(-1).to(feat.dtype))\n        h = h.view(b, s * k, -1)\n        pad = ~mask.unsqueeze(-1).expand(b, s, k).reshape(b, s * k)\n        pad = pad & ~pad.all(1, keepdim=True)  # a study with no series at all attends to everything\n        if self.tf is not None:\n            h = self.tf(h, src_key_padding_mask=pad)\n        a = self.att(h).float().masked_fill(pad.unsqueeze(-1), -1e4).softmax(1)  # [B, T, C]\n        pooled = torch.einsum("btc,btd->bcd", a.to(h.dtype), h)\n        return (pooled * self.cls_w).sum(-1) + self.cls_b\n\n    def forward(self, x, mask, pos, res=256, train=False, flip=False):\n        """x uint8 [B, S, K, 3, H, W]. flip: mirror coronal/axial series at random during training."""\n        b, s, k = x.shape[:3]\n        keep = mask.view(-1)  # run the backbone only on series that exist\n        xv = x.view(b * s, k, *x.shape[3:])[keep].flatten(0, 1)\n        flip_ok = None\n        if train and flip:\n            plane = torch.arange(s, device=x.device).repeat(b) % 3  # slot -> plane; 0 is sagittal\n            flip_ok = (plane != 0)[keep]\n        f = self.enc(make_views(xv, res, train, k, flip_ok=flip_ok).contiguous(memory_format=torch.channels_last))\n        feat = f.new_zeros(b * s, k, f.shape[-1])\n        feat[keep] = f.view(-1, k, f.shape[-1])\n        return self.head(feat.view(b, s, k, -1), mask, pos)', 'train.py': '"""Train one fold of my 2.5D knee reader on report-derived soft labels.\n\nInputs: the 256 px cache from src/preprocess.py (one .npy per series + *_meta.csv) and a CSV of\nsoft labels per study. The 58 gold-labelled studies are never trained on; every epoch reports\nmacro AUC on them (image truth) and on the fold\'s held-out soft labels (report proxy).\n\n    python src/train.py --fold 0 --folds 4 --backbone tf_efficientnetv2_s.in21k_ft_in1k\n"""\nimport argparse\nimport glob\nimport json\nimport math\nimport os\nimport time\n\nimport numpy as np\nimport pandas as pd\nimport torch\nfrom sklearn.metrics import roc_auc_score\n\nfrom knee import LABELS, KneeNet, StudyDataset, build_study_table\n\n\ndef find(pattern):\n    """Matches of a file pattern up to 3 folders deep under the input roots, shallowest first.\n    Roots: $KNEE_INPUT, Kaggle\'s inputs, the local data/ and outputs/ folders. A fixed depth\n    (not **) avoids crawling the ~819k DICOM files under train_series/."""\n    here = os.path.dirname(os.path.abspath(__file__))\n    roots = [r for r in [os.environ.get("KNEE_INPUT"), "/kaggle/input", f"{here}/../data", f"{here}/../outputs"] if r]\n    for root in roots:\n        for depth in range(4):\n            hits = sorted(glob.glob(os.path.join(root, *["*"] * depth, pattern)))\n            if hits:\n                return hits if pattern.startswith("cache") else hits[:1]\n    raise FileNotFoundError(pattern)\n\n\ndef load_cache():\n    """Returns (series -> npy path, series -> slice count) across all cache shards."""\n    paths, n_slices = {}, {}\n    for meta in find("cache256_train_meta.csv"):\n        d = meta.replace("_meta.csv", "")\n        m = pd.read_csv(meta)\n        m = m[m["error"].isna() & (m["n"] >= 3)] if "error" in m else m[m["n"] >= 3]\n        for sr, n in zip(m.series, m.n):\n            paths[sr], n_slices[sr] = f"{d}/{sr}.npy", int(n)\n    return paths, n_slices\n\n\ndef macro_auc(y, p):\n    aucs = [roc_auc_score(y[:, j], p[:, j]) for j in range(y.shape[1]) if 0 < y[:, j].sum() < len(y)]\n    return float(np.mean(aucs)) if aucs else float("nan")\n\n\n@torch.no_grad()\ndef predict(model, loader, device, res):\n    model.eval()\n    out = []\n    for x, mask, pos, _ in loader:\n        x, mask, pos = x.to(device), mask.to(device), pos.to(device)\n        with torch.autocast(device.type, dtype=torch.float16, enabled=device.type == "cuda"):\n            out.append(model(x, mask, pos, res=res).float().sigmoid().cpu())\n    return torch.cat(out).numpy() if out else np.zeros((0, len(LABELS)), np.float32)\n\n\ndef main():\n    ap = argparse.ArgumentParser()\n    ap.add_argument("--fold", type=int, default=0)\n    ap.add_argument("--folds", type=int, default=4)\n    ap.add_argument("--backbone", default="tf_efficientnetv2_s.in21k_ft_in1k")\n    ap.add_argument("--labels", default="llm_labels_v4_blend.csv")\n    ap.add_argument("--res", type=int, default=224)\n    ap.add_argument("--k", type=int, default=8, help="3-slice windows per series in training")\n    ap.add_argument("--k_eval", type=int, default=12)\n    ap.add_argument("--epochs", type=int, default=8)\n    ap.add_argument("--bs", type=int, default=4)\n    ap.add_argument("--lr", type=float, default=3e-4)\n    ap.add_argument("--wd", type=float, default=0.05)\n    ap.add_argument("--workers", type=int, default=4)\n    ap.add_argument("--limit", type=int, default=0, help="debug: use only this many training studies")\n    ap.add_argument("--out", default="/kaggle/working" if os.path.isdir("/kaggle/working") else "outputs")\n    args = ap.parse_args()\n    torch.manual_seed(args.fold)\n    np.random.seed(args.fold)\n    device = torch.device("cuda" if torch.cuda.is_available() else "mps" if torch.backends.mps.is_available() else "cpu")\n\n    train_csv = pd.read_csv(find("train.csv")[0])\n    series = pd.read_csv(find("train_series.csv")[0])\n    soft = pd.read_csv(find(args.labels)[0]).set_index("StudyInstanceUID")[LABELS]\n    paths, n_slices = load_cache()\n    table = build_study_table(series, n_slices)\n\n    gold = train_csv.dropna(subset=LABELS).set_index("StudyInstanceUID")[LABELS]\n    studies = sorted(s for s in table if s in soft.index and s not in gold.index)\n    rng = np.random.RandomState(42)  # same folds for every fold index\n    fold_of = dict(zip(studies, rng.permutation(len(studies)) % args.folds))\n    tr = [s for s in studies if fold_of[s] != args.fold]\n    va = [s for s in studies if fold_of[s] == args.fold]\n    gd = [s for s in gold.index if s in table]\n    if args.limit:\n        tr, va = tr[: args.limit], va[: max(4, args.limit // 4)]\n    print(f"device {device} | train {len(tr)} | val {len(va)} | gold {len(gd)} | series cached {len(paths)}", flush=True)\n\n    loader = lambda s: np.load(paths[s], mmap_mode="r")\n    ds = lambda st, y, k, train: StudyDataset(st, table, None, y, k=k, train=train, loader=loader)\n    dl = lambda d, shuffle: torch.utils.data.DataLoader(\n        d, batch_size=args.bs, shuffle=shuffle, num_workers=args.workers, drop_last=shuffle,\n        pin_memory=device.type == "cuda", persistent_workers=args.workers > 0)\n    train_dl = dl(ds(tr, soft.loc[tr].values.astype(np.float32), args.k, True), True)\n    val_dl = dl(ds(va, None, args.k_eval, False), False)\n    gold_dl = dl(ds(gd, None, args.k_eval, False), False)\n\n    model = KneeNet(args.backbone, pretrained=True, img_size=args.res).to(device)\n    if device.type == "cuda":\n        model = model.to(memory_format=torch.channels_last)\n    enc = [p for n, p in model.named_parameters() if n.startswith("enc.")]\n    rest = [p for n, p in model.named_parameters() if not n.startswith("enc.")]\n    opt = torch.optim.AdamW([{"params": enc, "lr": args.lr}, {"params": rest, "lr": args.lr * 3}], weight_decay=args.wd)\n    steps = args.epochs * len(train_dl)\n    warm = max(1, len(train_dl) // 2)\n    sched = torch.optim.lr_scheduler.LambdaLR(\n        opt, lambda i: min(1, (i + 1) / warm) * 0.5 * (1 + math.cos(math.pi * min(1.0, i / steps))))\n    scaler = torch.amp.GradScaler(enabled=device.type == "cuda")\n    loss_fn = torch.nn.BCEWithLogitsLoss()\n\n    os.makedirs(args.out, exist_ok=True)\n    tag = f"{args.backbone.split(\'.\')[0]}_r{args.res}_f{args.fold}"\n    log = []\n    for ep in range(args.epochs):\n        model.train()\n        t0, tot, n = time.time(), 0.0, 0\n        for x, mask, pos, y in train_dl:\n            x, mask, pos, y = x.to(device), mask.to(device), pos.to(device), y.to(device)\n            with torch.autocast(device.type, dtype=torch.float16, enabled=device.type == "cuda"):\n                logits = model(x, mask, pos, res=args.res, train=True, flip=True)\n            loss = loss_fn(logits.float(), y)\n            opt.zero_grad(set_to_none=True)\n            scaler.scale(loss).backward()\n            scaler.unscale_(opt)\n            torch.nn.utils.clip_grad_norm_(model.parameters(), 2.0)\n            scaler.step(opt)\n            scaler.update()\n            sched.step()\n            tot, n = tot + loss.item() * len(y), n + len(y)\n        pv, pg = predict(model, val_dl, device, args.res), predict(model, gold_dl, device, args.res)\n        row = {"epoch": ep, "loss": tot / max(n, 1), "minutes": (time.time() - t0) / 60,\n               "val_auc_vs_reports": macro_auc((soft.loc[va].values > 0.5).astype(int), pv),\n               "gold_auc": macro_auc(gold.loc[gd].values.astype(int), pg)}\n        log.append(row)\n        print(json.dumps({k: round(v, 4) if isinstance(v, float) else v for k, v in row.items()}), flush=True)\n\n    torch.save({"model": model.state_dict(), "args": {"backbone": args.backbone, "res": args.res}, "log": log},\n               f"{args.out}/{tag}.pt")\n    pd.DataFrame(pv, index=pd.Index(va, name="StudyInstanceUID"), columns=LABELS).to_csv(f"{args.out}/oof_{tag}.csv")\n    pd.DataFrame(pg, index=pd.Index(gd, name="StudyInstanceUID"), columns=LABELS).to_csv(f"{args.out}/gold_{tag}.csv")\n    json.dump({"args": vars(args), "log": log}, open(f"{args.out}/log_{tag}.json", "w"), indent=1)\n    print("saved", tag)\n\n\nif __name__ == "__main__":\n    main()\n'}

import os, subprocess, sys
os.makedirs("/kaggle/working/src", exist_ok=True)
for name, code in SOURCES.items():
    with open(f"/kaggle/working/src/{name}", "w") as f:
        f.write(code)
procs = []
for gpu, fold in enumerate([0, 1]):
    env = dict(os.environ, CUDA_VISIBLE_DEVICES=str(gpu))
    cmd = [sys.executable, "-u", "/kaggle/working/src/train.py", "--fold", str(fold), "--workers", "2"] + ['--epochs', '8']
    log = open(f"/kaggle/working/train_f{fold}.log", "w")
    procs.append((fold, subprocess.Popen(cmd, env=env, stdout=log, stderr=subprocess.STDOUT), log))
for fold, p, log in procs:
    p.wait()
    log.close()
    print(f"===== fold {fold} exit {p.returncode}")
    print(open(f"/kaggle/working/train_f{fold}.log").read()[-4000:])
